#include <stdint.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>
#include <stddef.h>
#include <stdarg.h>
#include <string.h>
#include "picotls.h"
#include "picotls/asn1.h"
#include "picotls/minicrypto.h"

static struct feeder {
    const uint8_t *data;
    size_t size;
} feeder;

static void feeder_init(const uint8_t *orig_data, size_t orig_size)
{
    feeder.data = orig_data;
    feeder.size = orig_size;
}

static uint8_t feeder_next_byte(void)
{
    if (feeder.size == 0) {
        return 0;
    }
    uint8_t byte = *feeder.data;
    --feeder.size;
    ++feeder.data;
    return byte;
}

void count_printf(void *ctx, const char *format, ...)
{
    int *c = ctx;
    va_list argptr;
    va_start(argptr, format);
    c += vsnprintf(NULL, 0, format, argptr);
    va_end(argptr);
    return;
}

int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
{
    int i, counter, indefinite_length, decode_error;
    ptls_minicrypto_log_ctx_t ctx = {&counter, count_printf};
    uint8_t *bytes, expected_type;
    size_t last_byte, bytes_max, byte_index;
    uint32_t length;
    uint8_t ret;

    feeder_init(Data, Size);

    bytes_max = (feeder_next_byte() << 8) + feeder_next_byte();
    if (bytes_max == 0)
        return 0;

    /* fill the test buffer */
    bytes = malloc(bytes_max);
    for (i = 0; i < (int)bytes_max; i++) {
        bytes[i] = feeder_next_byte();
    }

    ret = feeder_next_byte() % 4;
    if (ret == 0) {
        ptls_asn1_validation(bytes, bytes_max, &ctx);
    } else if (ret == 1) {
        byte_index = (feeder_next_byte() << 8) + feeder_next_byte();
        byte_index = byte_index % bytes_max;
        expected_type = feeder_next_byte();
        ptls_asn1_get_expected_type_and_length(bytes, bytes_max, byte_index, expected_type, &length, &indefinite_length, &last_byte,
                &decode_error, &ctx);
    } else if (ret == 2 || ret == 3) {
        ptls_context_t ptls_ctx = {0};
        char fname[] = "/tmp/fuzz_XXXXXX";
        int fd;
        ssize_t wr;
        fd = mkstemp(fname);
        if (fd < 0) {
            goto out;
        }
        wr = write(fd, bytes, bytes_max);
        if (wr != (ssize_t)bytes_max) {
            close(fd);
            unlink(fname);
            goto out;
        }
        close(fd);
        ptls_ctx.random_bytes = ptls_minicrypto_random_bytes;
        ptls_ctx.get_time = &ptls_get_time;
        ptls_ctx.key_exchanges = ptls_minicrypto_key_exchanges;
        ptls_ctx.cipher_suites = ptls_minicrypto_cipher_suites;

        if (ret == 2) {
            ptls_load_certificates(&ptls_ctx, fname);
            if (ptls_ctx.certificates.list) {
                for (i = 0; i < (int)ptls_ctx.certificates.count; i++) {
                    if (ptls_ctx.certificates.list[i].base)
                        free(ptls_ctx.certificates.list[i].base);
                }
                free(ptls_ctx.certificates.list);
            }
        } else {
            ptls_minicrypto_load_private_key(&ptls_ctx, fname);
        }
        unlink(fname);
    }
out:
    free(bytes);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    size_t size = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *data = malloc(size);
    fread(data, 1, size, f);
    fclose(f);
    int r = LLVMFuzzerTestOneInput(data, size);
    free(data);
    return r;
}
EOF

